// Generated by OrchestKit Claude Plugin
// Created: 2026-11-06

// Build-time source map upload to PostHog error tracking. capture_exceptions has
// been on since instrumentation-client.ts landed, but production serves no maps
// (0 of 27 chunks on 2026-11-06), so every minified frame stays unreadable until
// the build uploads them.
//
// Gated on the key's SHAPE, not its presence: a personal API key starts phx_.
// Anything else (unset, the literal "[SENSITIVE]" a `vercel pull` writes, or a
// phc_ project key pasted into the wrong variable) must degrade to "no upload",
// never to "no deploy". Portfolio lost a production deploy to the presence-only
// version of this check (run 34022392986).

export const POSTHOG_PROJECT_ID = "236036";

/** Returns the key when it is a personal API key, otherwise undefined. */
export function sourceMapUploadKey(raw) {
	return raw?.startsWith("phx_") ? raw : undefined;
}

/**
 * Wraps the Next config for upload, or returns it untouched. The wrapper is an
 * optional dependency: its CLI downloads from releases.posthog.com at install
 * time, and when that fails npm drops the package. A missing package must cost
 * the upload, never the install or the deploy.
 */
export async function withSourceMapUpload(
	site,
	env,
	// @vite-ignore: Vite resolves literal imports, and this one may be absent.
	load = () => import(/* @vite-ignore */ "@posthog/nextjs-config"),
) {
	const key = sourceMapUploadKey(env.POSTHOG_API_KEY);
	if (!key) {
		if (env.POSTHOG_API_KEY) {
			console.warn(
				"[posthog] POSTHOG_API_KEY is set but has no phx_ prefix; skipping source map upload.",
			);
		}
		return site;
	}
	try {
		const { withPostHogConfig } = await load();
		return withPostHogConfig(
			site,
			sourceMapUploadConfig(key, env.VERCEL_GIT_COMMIT_SHA),
		);
	} catch (error) {
		console.warn(
			`[posthog] @posthog/nextjs-config is not available; skipping source map upload: ${error}`,
		);
		return site;
	}
}

/** Options for withPostHogConfig. Pure so a test can pin them without a build. */
export function sourceMapUploadConfig(personalApiKey, commitSha) {
	return {
		personalApiKey,
		projectId: POSTHOG_PROJECT_ID,
		// App host, not the ingest host: the CLI talks to the PostHog API.
		host: "https://eu.posthog.com",
		sourcemaps: {
			enabled: true,
			releaseName: "orchestkit-docs",
			releaseVersion: commitSha ?? "local",
			// The site must keep serving no .map files.
			deleteAfterUpload: true,
			// Bound to the release above, the mode portfolio runs in production.
			releaseMode: "symbol-set",
			// Defaults to true. A PostHog outage or a revoked key must cost
			// readable stack traces, never a docs deploy.
			failOnError: false,
		},
	};
}
